/**
 * @module @kekenik/ui/app/zip-payload
 * 1-click download helper for KekenikPixel_final_source.zip.
 */

export const AGENT5_ZIP_BASE64 = "";
export const AGENT3_ZIP_BASE64 = AGENT5_ZIP_BASE64;

export function downloadAgent5Zip(): void {
  if (AGENT5_ZIP_BASE64) {
    const bin = atob(AGENT5_ZIP_BASE64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) {
      bytes[i] = bin.charCodeAt(i);
    }
    const blob = new Blob([bytes], { type: "application/zip" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "KekenikPixel_final_source.zip";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    return;
  }
  const a = document.createElement("a");
  a.href = "/KekenikPixel_final_source.zip";
  a.download = "KekenikPixel_final_source.zip";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

export const downloadAgent3Zip = downloadAgent5Zip;
